import { Component, EventEmitter, Input, Output, signal, inject, computed, effect, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule, DatePipe, UpperCasePipe } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, FormArray, AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';
import { ClinicalService, ConsultaMedica, Medicamento } from '../../../../core/services/clinical.service';
import { AppointmentService } from '../../../../core/services/appointment.service';
import { Cita, AppointmentStatus } from '../../../../core/models/appointment.model';

export const prescriptionValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
  const indicaciones = control.get('indicaciones')?.value;
  const medicamentos = control.get('medicamentos') as FormArray;
  
  const hasIndicaciones = indicaciones && indicaciones.trim().length > 0;
  const hasMedicamentos = medicamentos && medicamentos.length > 0;
  
  if (!hasIndicaciones && !hasMedicamentos) {
    return { prescriptionRequired: true };
  }
  
  return null;
};

@Component({
  selector: 'app-clinical-drawer',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './clinical-drawer.html',
  styleUrls: ['./clinical-drawer.scss']
})
export class ClinicalDrawerComponent implements OnChanges {
  private fb = inject(FormBuilder);
  private clinicalService = inject(ClinicalService);
  private appointmentService = inject(AppointmentService);

  @Input() isOpen = false;
  @Input() cita: Cita | null = null;
  @Output() closed = new EventEmitter<void>();
  @Output() consultationFinished = new EventEmitter<void>();

  clinicalForm: FormGroup;
  isLoading = signal(false);
  activeTab = signal<'clinical' | 'prescription' | 'history'>('clinical');
  history = signal<ConsultaMedica[]>([]);

  // Estado del resumen post-consulta
  showSummary = signal(false);
  summaryData = signal<ConsultaMedica | null>(null);
  atencionInicioReal = signal<string | null>(null);

  constructor() {
    this.clinicalForm = this.fb.group({
      diagnostico: ['', [Validators.required, Validators.minLength(5)]],
      procedimientoRealizado: ['', [Validators.required]],
      indicaciones: [''],
      observacionesInternas: [''],
      medicamentos: this.fb.array([])
    }, { validators: prescriptionValidator });
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['isOpen'] && this.isOpen) {
      if (this.cita?.id) {
        this.atencionInicioReal.set(new Date().toISOString());
        this.loadExistingConsultation();
        this.loadHistory();
      }
    }
  }

  private loadHistory() {
    if (!this.cita?.pacienteId) return;
    this.clinicalService.obtenerHistorial(this.cita.pacienteId).subscribe({
      next: (res) => {
        if (res.ok) {
          // Filtrar la consulta actual si ya existe para no mostrarla en el historial
          this.history.set(res.result!.filter(h => h.citaId !== this.cita?.id));
        }
      }
    });
  }

  get medicamentos() {
    return this.clinicalForm.get('medicamentos') as FormArray;
  }

  addMedicamento() {
    const medGroup = this.fb.group({
      nombre: ['', Validators.required],
      dosis: ['', Validators.required],
      frecuencia: ['', Validators.required],
      duracion: ['', Validators.required],
      instrucciones: ['']
    });
    this.medicamentos.push(medGroup);
    this.activeTab.set('prescription');
  }

  removeMedicamento(index: number) {
    this.medicamentos.removeAt(index);
  }

  private loadExistingConsultation() {
    this.isLoading.set(true);
    this.clinicalService.obtenerPorCita(this.cita!.id!).subscribe({
      next: (res) => {
        if (res.ok && res.result) {
          const data = res.result;
          this.clinicalForm.patchValue({
            diagnostico: data.diagnostico,
            procedimientoRealizado: data.procedimientoRealizado,
            indicaciones: data.indicaciones,
            observacionesInternas: data.observacionesInternas
          });

          // Cargar medicamentos
          this.medicamentos.clear();
          data.prescripcionMedica?.forEach(m => {
            this.medicamentos.push(this.fb.group(m));
          });
        }
        this.isLoading.set(false);
      },
      error: () => this.isLoading.set(false)
    });
  }

  onSubmit() {
    if (this.clinicalForm.invalid || !this.cita) {
      this.clinicalForm.markAllAsTouched();
      return;
    }

    this.isLoading.set(true);
    const formValue = this.clinicalForm.value;
    
    const consulta: ConsultaMedica = {
      citaId: this.cita.id!,
      pacienteId: this.cita.pacienteId,
      doctorId: this.cita.doctorId!,
      diagnostico: formValue.diagnostico,
      procedimientoRealizado: formValue.procedimientoRealizado,
      prescripcionMedica: formValue.medicamentos,
      indicaciones: formValue.indicaciones,
      observacionesInternas: formValue.observacionesInternas,
      atencionInicio: this.atencionInicioReal(),
      atencionFin: new Date().toISOString()
    };

    this.clinicalService.guardarConsulta(consulta).subscribe({
      next: (res) => {
        this.isLoading.set(false);
        if (res.ok && res.result) {
          // En lugar de cerrar, mostramos el resumen de la cita
          this.summaryData.set(res.result);
          this.showSummary.set(true);
          this.consultationFinished.emit();
        }
      },
      error: () => this.isLoading.set(false)
    });
  }

  /** Cierra el panel de resumen y el drawer completo */
  closeSummary() {
    this.showSummary.set(false);
    this.summaryData.set(null);
    this.closeDrawer();
  }

  /** Imprime el resumen de la cita usando un diseño limpio y premium */
  printSummary() {
    const data = this.summaryData();
    if (!data) return;

    const printWindow = window.open('', '_blank', 'width=900,height=1000');
    if (!printWindow) return;

    const fecha = this.cita?.fechaHora
      ? new Date(this.cita.fechaHora).toLocaleDateString('es-MX', { day: '2-digit', month: 'long', year: 'numeric' })
      : new Date().toLocaleDateString('es-MX', { day: '2-digit', month: 'long', year: 'numeric' });

    let medicamentosHtml = '';
    if (data.prescripcionMedica && data.prescripcionMedica.length > 0) {
      medicamentosHtml = `
        <div class="section">
          <div class="section-title">Receta Médica</div>
          <table class="meds-table">
            <thead>
              <tr>
                <th>Medicamento</th>
                <th>Dosis</th>
                <th>Frecuencia</th>
                <th>Duración</th>
              </tr>
            </thead>
            <tbody>
            ${data.prescripcionMedica.map(med => `
              <tr>
                <td><strong>${med.nombre}</strong></td>
                <td>${med.dosis}</td>
                <td>${med.frecuencia}</td>
                <td>${med.duracion}</td>
              </tr>
              ${med.instrucciones ? `<tr><td colspan="4" class="med-instructions">Nota: ${med.instrucciones}</td></tr>` : ''}
            `).join('')}
            </tbody>
          </table>
        </div>
      `;
    }

    let indicacionesHtml = '';
    if (data.indicaciones) {
      indicacionesHtml = `
        <div class="section">
          <div class="section-title">Indicaciones y Cuidados Post-operatorios</div>
          <div class="section-content indications-text">${data.indicaciones}</div>
        </div>
      `;
    }

    const doctorNombre = data.doctorNombre || this.cita?.doctorNombre || 'Doctor Tratante';

    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
        <head>
          <title>Resumen Clínico - ${this.cita?.pacienteNombre || 'Paciente'}</title>
          <style>
            @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');
            * { margin: 0; padding: 0; box-sizing: border-box; }
            body { font-family: 'Inter', sans-serif; color: #1e293b; padding: 2rem; font-size: 11px; background: white; line-height: 1.4; }
            .print-container { max-width: 800px; margin: 0 auto; }
            
            /* Header */
            .print-header { text-align: center; margin-bottom: 1.5rem; padding-bottom: 1rem; border-bottom: 1px solid #cbd5e1; }
            .print-header h1 { font-size: 1.4rem; font-weight: 900; color: #0f172a; text-transform: uppercase; letter-spacing: 0.05em; }
            .print-header p { color: #64748b; font-size: 0.8rem; font-weight: 500; margin-top: 0.2rem; }
            
            /* Meta Info Flex */
            .meta-info { display: flex; justify-content: space-between; margin-bottom: 1.5rem; padding-bottom: 1rem; border-bottom: 1px dashed #cbd5e1; }
            .meta-column { display: flex; flex-direction: column; gap: 0.5rem; }
            .meta-item { display: flex; gap: 0.5rem; }
            .meta-label { font-weight: 700; color: #64748b; width: 100px; text-transform: uppercase; font-size: 0.7rem; }
            .meta-value { font-weight: 600; color: #0f172a; }
            
            /* Sections */
            .section { margin-bottom: 1.25rem; page-break-inside: avoid; }
            .section-title { font-size: 0.75rem; font-weight: 800; color: #0f172a; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 0.4rem; border-bottom: 1px solid #e2e8f0; padding-bottom: 0.2rem; display: inline-block; width: 100%; }
            .section-content { font-size: 0.85rem; color: #334155; white-space: pre-wrap; padding-top: 0.2rem; }
            
            /* Medications Table */
            .meds-table { width: 100%; border-collapse: collapse; margin-top: 0.5rem; }
            .meds-table th { text-align: left; padding: 0.4rem; background: #f8fafc; font-size: 0.7rem; color: #64748b; text-transform: uppercase; border: 1px solid #e2e8f0; }
            .meds-table td { padding: 0.4rem; border: 1px solid #e2e8f0; font-size: 0.85rem; color: #1e293b; }
            .med-instructions { font-style: italic; color: #64748b !important; font-size: 0.75rem !important; background: #fafafa; padding-left: 1rem !important; }
            
            /* Indications */
            .indications-text { font-weight: 500; color: #0f172a; border-left: 3px solid #cbd5e1; padding-left: 0.75rem; }
            
            /* Footer Signature */
            .footer { margin-top: 3rem; display: flex; justify-content: center; page-break-inside: avoid; }
            .signature-box { text-align: center; width: 250px; }
            .signature-line { border-bottom: 1px solid #0f172a; height: 40px; margin-bottom: 0.5rem; }
            .doctor-name { font-size: 0.85rem; font-weight: 800; color: #0f172a; }
            .doctor-title { font-size: 0.7rem; font-weight: 600; color: #64748b; text-transform: uppercase; }
            
            @media print { 
              @page { margin: 1cm; size: portrait; }
              body { padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; } 
              .print-container { width: 100%; max-width: 100%; } 
            }
          </style>
        </head>
        <body>
          <div class="print-container">
            <div class="print-header">
              <h1>Hoja Clínica y Receta</h1>
              <p>MEYISOFT DENTAL POS</p>
            </div>
            
            <div class="meta-info">
              <div class="meta-column">
                <div class="meta-item">
                  <span class="meta-label">Paciente:</span>
                  <span class="meta-value">${this.cita?.pacienteNombre || 'N/A'}</span>
                </div>
                <div class="meta-item">
                  <span class="meta-label">Servicio:</span>
                  <span class="meta-value">${this.cita?.servicioNombre || 'Consulta General'}</span>
                </div>
              </div>
              <div class="meta-column">
                <div class="meta-item">
                  <span class="meta-label">Fecha:</span>
                  <span class="meta-value">${fecha}</span>
                </div>
                <div class="meta-item">
                  <span class="meta-label">Doctor(a):</span>
                  <span class="meta-value">${doctorNombre}</span>
                </div>
              </div>
            </div>

            <div class="section">
              <div class="section-title">Hallazgos y Diagnóstico</div>
              <div class="section-content">${data.diagnostico}</div>
            </div>

            <div class="section">
              <div class="section-title">Procedimiento Realizado</div>
              <div class="section-content">${data.procedimientoRealizado}</div>
            </div>

            ${medicamentosHtml}
            ${indicacionesHtml}

            <div class="footer">
              <div class="signature-box">
                <div class="signature-line"></div>
                <div class="doctor-name">Dr(a). ${doctorNombre}</div>
                <div class="doctor-title">Odontólogo Tratante</div>
              </div>
            </div>
          </div>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => {
      printWindow.print();
      printWindow.close();
    }, 500);
  }

  closeDrawer() {
    this.closed.emit();
    this.clinicalForm.reset();
    this.medicamentos.clear();
    this.activeTab.set('clinical');
    this.showSummary.set(false);
    this.summaryData.set(null);
  }
}
